namespace Lurp.Tests;

/// <summary>
///     Phase 11 generated-code provenance proof: verifies that generated files are
///     correctly identified and cross-generated edges are marked.
/// </summary>
public sealed class GeneratedCodeProvenanceTests : InMemoryTestBase
{
    private const string HandWrittenDoc = "HandWritten.cs";
    private const string GeneratedDoc = "Widget.g.cs";

    private static Dictionary<string, string> TwoFiles(string handWritten, string generated)
    {
        return new Dictionary<string, string>
        {
            [HandWrittenDoc] = handWritten,
            [GeneratedDoc] = generated
        };
    }

    [Fact]
    public async Task GeneratedFile_MarksDeclarationsAndCrossGeneratedEdges()
    {
        var extraction = await ExtractAsync(TwoFiles("""
                                                     namespace N;
                                                     public class HandWritten
                                                     {
                                                         public void DoWork() { }
                                                     }
                                                     """, """
                                                          // <auto-generated/>
                                                          namespace N;
                                                          public class Widget : HandWritten
                                                          {
                                                              public void Process() { DoWork(); }
                                                          }
                                                          """));

        var declarations = extraction.Result.Declarations;

        var handWrittenDecl = declarations.Single(d => d.SymbolId.FullyQualifiedName == "global::N.HandWritten");
        var widgetDecl = declarations.Single(d => d.SymbolId.FullyQualifiedName == "global::N.Widget");

        Assert.False(handWrittenDecl.IsGenerated, "Hand-written declarations should have IsGenerated == false");
        Assert.True(widgetDecl.IsGenerated, "Generated file declarations should have IsGenerated == true");

        var inheritsEdge = extraction.SingleEdge("Inherits", "global::N.Widget", "global::N.HandWritten");
        Assert.True(inheritsEdge.IsCrossGenerated,
            "Inherits edge from generated file should have IsCrossGenerated == true");

        var handWrittenDeclaresDoWork =
            extraction.SingleEdge("Declares", "global::N.HandWritten", "global::N.HandWritten.DoWork");
        Assert.False(handWrittenDeclaresDoWork.IsCrossGenerated,
            "Declares edge from hand-written file should have IsCrossGenerated == false");

        var widgetDeclaresProcess = extraction.SingleEdge("Declares", "global::N.Widget", "global::N.Widget.Process");
        Assert.True(widgetDeclaresProcess.IsCrossGenerated,
            "Declares edge from generated file should have IsCrossGenerated == true");

        var callsEdge = extraction.SingleEdge("Calls", "global::N.Widget.Process", "global::N.HandWritten.DoWork");
        Assert.True(callsEdge.IsCrossGenerated, "Calls edge from generated file should have IsCrossGenerated == true");
    }

    [Fact]
    public async Task DeriveGeneratorIdentity_UsesGeneratedCodeOrdinalRuleWithoutByteCap()
    {
        var longLicense = string.Concat(Enumerable.Repeat("// Copyright (c) Example Corp. All rights reserved. License line.\n", 20));
        Assert.True(longLicense.Length > 512);

        var extraction = await ExtractAsync(new Dictionary<string, string>
        {
            ["LateAutoGen.cs"] = longLicense + "// <auto-generated> LateTool\nnamespace N;\npublic class LateAutoGen { }\n",
            ["BlockAutoGen.cs"] = "/* <autogenerated> BlockTool */\nnamespace N;\npublic class BlockAutoGen { }\n",
            ["SelfClose.cs"] = "// <auto-generated/>\nnamespace N;\npublic class SelfClose { }\n",
            ["UpperCase.g.cs"] = "// <AUTO-GENERATED> UpperTool\nnamespace N;\npublic class UpperCase { }\n",
            ["LateAttr.g.cs"] = longLicense + "using System.CodeDom.Compiler;\nnamespace N;\n[GeneratedCode(\"LateAttrTool\", \"1.0\")]\npublic class LateAttr { }\n"
        });

        var decls = extraction.Result.Declarations;

        var lateAutoGen = decls.Single(d => d.SymbolId.FullyQualifiedName == "global::N.LateAutoGen");
        Assert.True(lateAutoGen.IsGenerated);
        Assert.Equal("LateTool", lateAutoGen.GeneratorIdentity);

        var blockAutoGen = decls.Single(d => d.SymbolId.FullyQualifiedName == "global::N.BlockAutoGen");
        Assert.True(blockAutoGen.IsGenerated);
        Assert.Equal("BlockTool", blockAutoGen.GeneratorIdentity);

        var selfClose = decls.Single(d => d.SymbolId.FullyQualifiedName == "global::N.SelfClose");
        Assert.True(selfClose.IsGenerated);
        Assert.Equal("auto-generated-header", selfClose.GeneratorIdentity);

        var upperCase = decls.Single(d => d.SymbolId.FullyQualifiedName == "global::N.UpperCase");
        Assert.True(upperCase.IsGenerated);
        Assert.Null(upperCase.GeneratorIdentity);

        var lateAttr = decls.Single(d => d.SymbolId.FullyQualifiedName == "global::N.LateAttr");
        Assert.True(lateAttr.IsGenerated);
        Assert.Equal("LateAttrTool", lateAttr.GeneratorIdentity);
    }
}